import{_ as r,c as s,o as a,ah as t,j as e,a as i}from"./chunks/framework.D-P5O0CF.js";const l="/Qonnectra-docs/pr-16/images/manual/teil-a/valuation.jpg",d="/Qonnectra-docs/pr-16/images/manual/teil-a/valuation_area.jpg",o="/Qonnectra-docs/pr-16/videos/valuation_area_select.webm",h="/Qonnectra-docs/pr-16/images/manual/teil-a/valuation_year.jpg",u="/Qonnectra-docs/pr-16/images/manual/teil-a/valuation_result.jpg",c="/Qonnectra-docs/pr-16/images/manual/teil-a/valuation_kpi.jpg",g="/Qonnectra-docs/pr-16/images/manual/teil-a/valuation_projection.jpg",_=JSON.parse('{"title":"9. Wertermittlung","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/09-wertermittlung.md","filePath":"manual/teil-a-anwenderhandbuch/09-wertermittlung.md"}'),b={name:"manual/teil-a-anwenderhandbuch/09-wertermittlung.md"};function m(p,n,k,w,z,f){return a(),s("div",null,[...n[0]||(n[0]=[t('<h1 id="_9-wertermittlung" tabindex="-1">9. Wertermittlung <a class="header-anchor" href="#_9-wertermittlung" aria-label="Permalink to &quot;9. Wertermittlung&quot;">​</a></h1><p>Die <strong>Wertermittlung</strong> rechnet aus, was ein Netz gekostet hat oder heute kosten würde: Sie zählt die Mengen im gewählten Gebiet – Trassenlänge und Netzknoten je Art – und multipliziert sie mit den Kostensätzen, die für das Projekt hinterlegt sind. Das Ergebnis ist eine Aufstellung nach Kostenbereichen, die Gesamtinvestition, zwei Kennzahlen und eine Fortschreibung über die kommenden Jahre. Sie erreichen sie über die linke Navigationsleiste in der Gruppe „Funktionen“ durch Klicken auf den Menüpunkt „Wertermittlung“.</p><p><img src="'+l+'" alt="Screenshot Wertermittlung mit der Karte links und dem Bedienfeld rechts" data-zoomable="true"></p><p>Links liegt die Karte, rechts das Bedienfeld mit der Gebietsauswahl, den Eingaben für die Fortschreibung und dem Button „Berechnen“. Das Ergebnis erscheint unter dem Button im selben Feld. Gerechnet wird ausschließlich; am Datenbestand ändert die Wertermittlung nichts, und das Ergebnis wird nicht gespeichert.</p><p>Die Karte verhält sich wie in Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-3-das-kartenfenster">Das Kartenfenster</a> beschrieben, mit einer Ausnahme: Ein Klick wählt hier kein Objekt aus und öffnet keine Info-Box, sondern schaltet ein Gebiet in der Auswahl an oder ab, siehe Abschnitt <a href="#_9-1-gebiet-oder-gesamtprojekt-wahlen">Gebiet oder Gesamtprojekt wählen</a>.</p><h2 id="_9-1-gebiet-oder-gesamtprojekt-wahlen" tabindex="-1">9.1 Gebiet oder Gesamtprojekt wählen <a class="header-anchor" href="#_9-1-gebiet-oder-gesamtprojekt-wahlen" aria-label="Permalink to &quot;9.1 Gebiet oder Gesamtprojekt wählen&quot;">​</a></h2><p>Der Bereich „Gebiet auswählen“ oben im Bedienfeld bestimmt, worüber gerechnet wird. Beim Öffnen der Ansicht ist „Gesamt (ganzes Projekt)“ angehakt.</p><p>Darunter stehen die Gebiete des Projekts, gruppiert nach Gebietstyp; hinter jedem Gruppennamen steht die Anzahl, und ein Klick darauf klappt die Gruppe zu und wieder auf. Gebiete ohne Typ sammelt die Gruppe „Sonstige“. Was ein Gebiet ist, erklärt Abschnitt <a href="./02-grundbegriffe-und-datenmodell.html#_2-5-gebiet-und-gebietstyp">Gebiet und Gebietstyp</a>.</p><p>Sie wählen entweder das Gesamtprojekt oder einzelne Gebiete:</p><ul><li>Ein Häkchen an einem Gebiet nimmt das Häkchen bei „Gesamt (ganzes Projekt)“ weg.</li><li>Ein Häkchen bei „Gesamt (ganzes Projekt)“ hebt die Gebietsauswahl auf.</li><li>Mehrere Gebiete lassen sich gleichzeitig anhaken; gerechnet wird dann über deren Gesamtfläche.</li></ul><p>Die gewählten Gebiete umrandet die Karte orange. Umgekehrt geht es genauso: Ein Klick auf ein Gebiet in der Karte setzt oder entfernt dessen Häkchen in der Liste.</p><p><img src="'+d+'" alt="Screenshot Wertermittlung mit Hervorhebung der Gebietsauswahl im Bedienfeld und des orange umrandeten Gebiets in der Karte" data-zoomable="true"></p>',12),e("p",null,[e("video",{src:o,controls:"",playsinline:"",preload:"metadata"},[i(" Ihr Browser unterstützt das Abspielen von HTML5-Videos nicht. Sie können die Datei "),e("a",{href:"/videos/valuation_area_select.webm",download:""},"herunterladen"),i(" anstelle des Videos. ")])],-1),t('<p>Ist weder „Gesamt“ noch ein Gebiet gewählt, bleibt „Berechnen“ ausgeschaltet und darunter steht der Hinweis „Wähle ein Ausbaugebiet oder „Gesamt“, um die Wertermittlung zu starten.“</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Sind für das Projekt keine Gebiete hinterlegt, steht anstelle der Liste „Keine Ausbaugebiete für dieses Projekt vorhanden.“ Über „Gesamt (ganzes Projekt)“ können Sie dann trotzdem rechnen.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Neben der Projektauswahl in der Kopfzeile liegt in dieser Ansicht die Schaltfläche „Alle Projekte anzeigen“, siehe Abschnitt <a href="./01-erste-schritte.html#_1-3-projekt-auswahlen-und-wechseln">Projekt auswählen und wechseln</a>. Eingeschaltet listet die Gebietsauswahl die Gebiete <strong>aller</strong> Projekte auf – gerechnet wird aber weiterhin nur über das Projekt aus der Kopfzeile. Haken Sie ein Gebiet eines anderen Projekts an, wird es stillschweigend übergangen und Sie erhalten das Ergebnis für das ganze aktuelle Projekt, als hätten Sie „Gesamt“ gewählt. Lassen Sie die Schaltfläche für die Wertermittlung deshalb ausgeschaltet.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Beim Umschalten dieser Schaltfläche wird die Auswahl auf „Gesamt“ zurückgesetzt und ein vorhandenes Ergebnis verworfen.</p></div><div class="danger custom-block"><p class="custom-block-title">Achtung</p><p>Ein Projektwechsel räumt dagegen nichts auf: Das Ergebnis des vorherigen Projekts bleibt im Bedienfeld stehen, und die Häkchen bleiben auf Gebieten, die es im neuen Projekt nicht gibt. Die Ansicht zeigt dann eine Aufstellung, die nicht zum Projekt in der Kopfzeile gehört – ohne jeden Hinweis darauf, und selbst dann, wenn für das neue Projekt gar keine Kostensätze hinterlegt sind. Rechnen Sie nach einem Projektwechsel neu, bevor Sie das Ergebnis lesen oder weitergeben.</p></div><h2 id="_9-2-jahr-des-bauabschlusses-und-jahrlicher-korrekturwert" tabindex="-1">9.2 Jahr des Bauabschlusses und jährlicher Korrekturwert <a class="header-anchor" href="#_9-2-jahr-des-bauabschlusses-und-jahrlicher-korrekturwert" aria-label="Permalink to &quot;9.2 Jahr des Bauabschlusses und jährlicher Korrekturwert&quot;">​</a></h2><p>Der Bereich „Zukunftsabhängige Wertermittlung“ enthält die beiden Eingaben für die Fortschreibung:</p><ul><li><strong>„Jahr Bauabschluss“</strong> – das Startjahr der Fortschreibung, vorbelegt mit dem laufenden Jahr.</li><li><strong>„Jährlicher Korrekturwert (%)“</strong> – die jährliche Veränderung in Prozent, vorbelegt mit 2,5. Darunter steht der Hinweis „Positiver Wert = Wiederherstellungswert, negativer Wert = Wertverfall.“, also: ein positiver Wert schreibt fort, was die Wiederherstellung des Netzes künftig kostet, ein negativer rechnet den Wertverlust.</li></ul><p><img src="'+h+'" alt="Screenshot Wertermittlung mit Hervorhebung der Felder „Jahr Bauabschluss“ und „Jährlicher Korrekturwert (%)“" data-zoomable="true"></p><p>Beide Eingaben wirken ausschließlich auf die Tabelle in Abschnitt <a href="#_9-6-zukunftsabhangige-wertermittlung">Zukunftsabhängige Wertermittlung</a>. Die Gesamtinvestition und die beiden Kennzahlen bleiben davon unberührt.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Nach einer Änderung müssen Sie <strong>nicht</strong> erneut auf „Berechnen“ klicken: Solange ein Ergebnis angezeigt wird, rechnet Qonnectra die Fortschreibung bei jeder Eingabe sofort neu.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die beiden leeren Felder verhalten sich unterschiedlich. Ohne „Jahr Bauabschluss“ verschwindet die Tabelle der Fortschreibung ganz. Ohne „Jährlicher Korrekturwert (%)“ bleibt sie stehen und rechnet mit 0 %: Alle Jahre stehen dann auf demselben Netzwert und die Spalte „Steigerung“ auf 0,00 €. Das ist keine Aussage über die Wertentwicklung, sondern nur ein fehlender Wert – lassen Sie das Feld nicht leer, wenn Sie die Tabelle weitergeben.</p></div><h2 id="_9-3-woher-die-kostensatze-kommen" tabindex="-1">9.3 Woher die Kostensätze kommen <a class="header-anchor" href="#_9-3-woher-die-kostensatze-kommen" aria-label="Permalink to &quot;9.3 Woher die Kostensätze kommen&quot;">​</a></h2><p>Die Kostensätze sind je Projekt hinterlegt und werden im Administrationsbereich gepflegt, siehe Kapitel <a href="./../teil-b-betrieb-admin-qgis/22-projektbezogene-konfiguration.html">Projektbezogene Konfiguration</a>. In der Wertermittlung selbst lassen sie sich nicht ändern; die Ansicht liest sie nur.</p><p>Jeder Kostensatz besteht aus einem Namen – dem <strong>Kostenbereich</strong> –, einem Betrag und einer Einheit. Die Einheit entscheidet, welche Menge Qonnectra dazu zählt:</p><ul><li><strong>„pro Meter“</strong> – die Länge der Trassen im gewählten Gebiet.</li><li><strong>„Stück“</strong> – die Anzahl der Netzknoten im gewählten Gebiet, und zwar nur derjenigen Netzknotentypen, die dem Kostensatz zugeordnet sind. Ein Kostensatz kann mehrere Typen zusammenfassen.</li></ul><p>Zusätzlich ist an den Kostensätzen vermerkt, welche davon einen Hausanschluss darstellen. Daraus entsteht die Kennzahl „Kosten pro Hausanschluss“, siehe Abschnitt <a href="#_9-5-kennzahlen-kosten-pro-meter-und-pro-hausanschluss">Kennzahlen</a>.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Sind für das Projekt keine Kostensätze hinterlegt, bleibt „Berechnen“ ausgeschaltet und darüber steht „Keine Kostensätze konfiguriert. Bitte im Adminbereich anlegen.“ Die Wertermittlung setzt damit – wie die Rohrverzweigung, siehe Kapitel <a href="./12-rohrverzweigung.html">Rohrverzweigung</a> – eine Vorarbeit der Administration voraus und ist ohne sie nicht benutzbar.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Ein Kostensatz mit der Einheit „Stück“, dem kein Netzknotentyp zugeordnet ist, kommt immer auf die Menge 0 und damit auf 0,00 €. Er steht dann mit Nullen in der Tabelle, ohne dass ein Fehler gemeldet wird. Erscheint ein Kostenbereich unerwartet mit 0, prüfen Sie zuerst seine Zuordnung der Netzknotentypen.</p></div><h2 id="_9-4-ergebnis-lesen-kostenbereich-menge-einheitspreis-gesamtinvestition" tabindex="-1">9.4 Ergebnis lesen: Kostenbereich, Menge, Einheitspreis, Gesamtinvestition <a class="header-anchor" href="#_9-4-ergebnis-lesen-kostenbereich-menge-einheitspreis-gesamtinvestition" aria-label="Permalink to &quot;9.4 Ergebnis lesen: Kostenbereich, Menge, Einheitspreis, Gesamtinvestition&quot;">​</a></h2><p>„Berechnen“ ermittelt die Mengen und stellt das Ergebnis unter dem Button dar. Die Tabelle hat vier Spalten:</p><ul><li><strong>„Kostenbereich“</strong> – der Name des Kostensatzes.</li><li><strong>„Kosten (EP)“</strong> – der Einheitspreis, dahinter die Einheit („/ Stück“ oder „/ pro Meter“).</li><li><strong>„Menge“</strong> – die gezählte Menge: Stückzahl oder Länge in Metern.</li><li><strong>„Gesamt (GP)“</strong> – Einheitspreis mal Menge.</li></ul><p>Die Fußzeile der Tabelle nennt als <strong>„Gesamtinvestition“</strong> die Summe aller Zeilen.</p><p><img src="'+u+'" alt="Screenshot Wertermittlung mit dem Ergebnis: Tabelle der Kostenbereiche, Gesamtinvestition und den beiden Kennzahlen" data-zoomable="true"></p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Bei einem gewählten Gebiet wird die Trassenlänge an der Gebietsgrenze abgeschnitten: Eine Trasse, die halb im Gebiet liegt, geht auch nur mit ihrer halben Länge ein. Netzknoten dagegen werden ganz gezählt oder gar nicht, je nachdem, ob sie im Gebiet liegen.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Gezählt wird der Bestand, wie er in Qonnectra erfasst ist. Fehlende Trassenlängen, nicht erfasste Netzknoten oder ein falscher Netzknotentyp verändern das Ergebnis unmittelbar, ohne dass die Ansicht darauf hinweist. Eine Wertermittlung ist deshalb nur so gut wie die Datenpflege des Projekts.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Ein neuer Klick auf „Berechnen“ ersetzt das angezeigte Ergebnis. Ein Vergleich zweier Gebiete nebeneinander ist in der Ansicht nicht möglich – notieren Sie das erste Ergebnis, bevor Sie das zweite rechnen.</p></div><h2 id="_9-5-kennzahlen-kosten-pro-meter-und-pro-hausanschluss" tabindex="-1">9.5 Kennzahlen: Kosten pro Meter und pro Hausanschluss <a class="header-anchor" href="#_9-5-kennzahlen-kosten-pro-meter-und-pro-hausanschluss" aria-label="Permalink to &quot;9.5 Kennzahlen: Kosten pro Meter und pro Hausanschluss&quot;">​</a></h2><p>Unter der Tabelle stehen zwei Kennzahlen:</p><ul><li><strong>„Kosten pro Hausanschluss“</strong> – die Gesamtinvestition geteilt durch die Anzahl der Netzknoten aus den Kostensätzen, die als Hausanschluss gekennzeichnet sind.</li><li><strong>„Gesamtkosten pro Meter“</strong> – die Gesamtinvestition geteilt durch die Trassenlänge.</li></ul><p><img src="'+c+'" alt="Screenshot Wertermittlung mit Hervorhebung der beiden Kennzahlen „Kosten pro Hausanschluss“ und „Gesamtkosten pro Meter“" data-zoomable="true"></p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Beide Kennzahlen teilen die <strong>gesamte</strong> Investition und nicht den Anteil des jeweiligen Kostenbereichs. „Kosten pro Hausanschluss“ ist also nicht der Preis eines Hausanschlusses, sondern der Anteil des gesamten Netzes, der auf einen Hausanschluss entfällt – Tiefbau, Verteiler und POP eingerechnet. Entsprechend ist „Gesamtkosten pro Meter“ höher als der Einheitspreis des Tiefbaus.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Gibt es im gewählten Gebiet keinen Hausanschluss oder keine Trasse, steht anstelle der Kennzahl ein Gedankenstrich.</p></div><h2 id="_9-6-zukunftsabhangige-wertermittlung" tabindex="-1">9.6 Zukunftsabhängige Wertermittlung <a class="header-anchor" href="#_9-6-zukunftsabhangige-wertermittlung" aria-label="Permalink to &quot;9.6 Zukunftsabhängige Wertermittlung&quot;">​</a></h2><p>Ganz unten im Bedienfeld steht die Fortschreibung unter der Überschrift „Zukunftsabhängige Wertermittlung“ mit den Spalten „Jahr“, „Netzwert“ und „Steigerung“. Sie beginnt beim Jahr aus „Jahr Bauabschluss“ und umfasst 22 Jahre. Der Netzwert des ersten Jahres ist die Gesamtinvestition; jedes weitere Jahr wird mit dem Korrekturwert aus Abschnitt <a href="#_9-2-jahr-des-bauabschlusses-und-jahrlicher-korrekturwert">Jahr des Bauabschlusses und jährlicher Korrekturwert</a> fortgeschrieben. „Steigerung“ ist die Veränderung gegenüber dem Vorjahr und bleibt im ersten Jahr leer.</p><p><img src="'+g+'" alt="Screenshot Wertermittlung mit Hervorhebung der Tabelle „Zukunftsabhängige Wertermittlung“" data-zoomable="true"></p><p>Der Korrekturwert wirkt auf den jeweils erreichten Wert und nicht auf den Ausgangswert; die Steigerung wächst deshalb von Jahr zu Jahr, auch wenn der Prozentsatz gleich bleibt. Bei einem negativen Korrekturwert fällt der Netzwert entsprechend, und in der Spalte „Steigerung“ stehen negative Beträge.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die Fortschreibung ist eine reine Zinsrechnung mit einem einzigen Prozentsatz. Sie kennt weder unterschiedliche Entwicklungen je Kostenbereich noch die Nutzungsdauer der Bauteile und ist damit eine Überschlagsrechnung, keine Bewertung nach handels- oder steuerrechtlichen Vorgaben.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Das Bedienfeld ist ein eigener Scrollbereich. Ist die Fortschreibung nicht zu sehen, scrollen Sie darin nach unten – die Karte links bleibt dabei stehen.</p></div>',39)])])}const G=r(b,[["render",m]]);export{_ as __pageData,G as default};
